/* Saved-record browsing only. No inference, new metrics, or implicit downloads. */
function archiveFilter(rows,query){
  const terms=String(query||'').trim().toLowerCase().split(/\s+/).filter(Boolean);
  return rows.filter(row=>terms.every(term=>JSON.stringify(row).toLowerCase().includes(term)));
}
function archiveSafeURL(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:null;}catch{return null;}}
function archiveURL(values){const query=new URLSearchParams({room:'research_archive'});for(const [key,value]of Object.entries(values))if(value!==null&&value!==undefined&&value!=='')query.set('ar_'+key,String(value));return '?'+query;}
if(typeof module!=='undefined')module.exports={archiveFilter,archiveSafeURL,archiveURL};
if(typeof window!=='undefined')(()=>{
  const data=__ARCHIVE_PAYLOAD__,doc=window.parent.document,stage=doc.querySelector('.ra-stage');
  if(!stage)return;
  const lettering=stage.querySelector('.ra-lettering-source');
  if(lettering){
    // One shared rule keeps the lossless atlas from being repeated in dozens
    // of inline styles. Attach to this render so the next room removes it.
    const artworkStyle=doc.createElement('style');
    artworkStyle.textContent='.ra-stage>.ra-reference-window{background-image:url('+JSON.stringify(lettering.src)+')!important}';
    stage.append(artworkStyle);
  }
  const dialog=stage.querySelector('.ra-dialog'),body=stage.querySelector('.ra-dialog-body');
  let previousFocus;
  const node=(tag,text,cls)=>{const n=doc.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n;};
  function p(text,cls){const n=node('p',text,cls);body.append(n);return n;}
  function open(title){if(!dialog.open)previousFocus=doc.activeElement;stage.querySelector('#ra-dialog-title').textContent=title;body.replaceChildren();if(!dialog.open)dialog.showModal();dialog.scrollTop=0;stage.querySelector('.ra-dialog-context').textContent='Controlled-300 archive · Saved evidence · Original sources';}
  function close(){dialog.close();previousFocus?.focus();}
  function button(label,action,parent=body){const n=node('button',label);n.type='button';if(/^(Open verified|Prepare verified|Load saved|Verify this)/.test(label))n.className='ra-primary';n.addEventListener('click',()=>action());parent.append(n);return n;}
  function link(label,url,parent=body){const safe=archiveSafeURL(url);if(!safe)return;const a=node('a',label,'ra-link');a.href=safe;a.target='_blank';a.rel='noopener noreferrer';parent.append(a);return a;}
  function jump(values){const a=node('a');a.href=archiveURL(values);a.target='_self';stage.append(a);stage.querySelector('.ra-sr').textContent='Loading exact saved Archive record…';a.click();a.remove();}
  function detail(title,value,parent=body){const d=node('details'),s=node('summary',title);d.append(s,node('pre',typeof value==='string'?value:JSON.stringify(value,null,2)));parent.append(d);}
